                                buyReason: "三逻辑定期组合控波调仓"
                            )
                            var latest: [AdvancedBacktestStrategyMode: [String: Double]] = [:]
                            var previousRaw: [String: Double] = [:]
                            var previousTarget: [String: Double] = [:]
