            let boostOptions = [1.25, 1.40]
            let mediumDrawdownOptions = [0.035, 0.045]
            let deepDrawdownOptions = [0.055, 0.065]
            let mediumGrossOptions = [0.45, 0.60]
            let reentryGrossOptions = [0.65, 0.85]
