            }
            let buckets: [(name: String, symbols: [String], prior: Double)] = [
                ("gold", ["gold_cny"], 1.10),
                ("us", ["nasdaq", "sp500", "dowjones"], 1.00),
                ("china", ["csi300", "shanghai_composite", "shenzhen_component", "chinext"], 0.85),
