                                    var latest: [AdvancedBacktestStrategyMode: [String: Double]] = [:]
                                    var pending: [String: Double] = [:]
                                    var previous: [String: Double] = [:]
                                    var state = 0
                                    var warningStreak = 0
                                    var crisisStreak = 0
                                    var recoveryStreak = 0
                                    var transitions = 0
